/** A scalloped disc's outline: the Pro seal (uiux offers spec §5.5), drawn from points, no asset. */
export function sealPath(cx: number, cy: number, outer: number, inner: number, points: number): string {
  let d = '';
  for (let i = 0; i < points * 2; i += 1) {
    const r = i % 2 === 1 ? inner : outer;
    const a = (Math.PI * i) / points - Math.PI / 2;
    d += `${i === 0 ? 'M' : 'L'}${(cx + r * Math.cos(a)).toFixed(2)} ${(cy + r * Math.sin(a)).toFixed(2)}`;
  }
  return `${d}Z`;
}

/** The four-point sparkle of the app's `sparkles` icon, at 24 units. */
export const SPARKLE_PATH = 'M12 3l1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8z';
