import { SPARKLE_PATH, sealPath } from './sealPath.js';
import styles from './Art.module.css';

const SMALL = sealPath(12, 12, 11, 9.2, 14);
const BIG = sealPath(60, 60, 56, 48, 20);

/**
 * The gold Pro seal: a scalloped disc with a check, in `currentColor` with
 * the check cut in the plate colour. Never mirrored in RTL: a check that
 * flips reads as a "V".
 */
export function Seal({
  size = 16,
  className,
}: {
  size?: number;
  className?: string | undefined;
}): React.JSX.Element {
  return (
    <svg
      className={className}
      viewBox="0 0 24 24"
      width={size}
      height={size}
      aria-hidden="true"
      focusable="false"
    >
      <path fill="currentColor" d={SMALL} />
      <path
        d="M8 12.4l2.6 2.6L16.2 9.4"
        fill="none"
        stroke="var(--gold-soft)"
        strokeWidth="2.2"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/** The 112px seal of a takeover, with its ring; it pops in unless motion is reduced. */
export function SealBig({ className }: { className?: string | undefined }): React.JSX.Element {
  return (
    <svg className={className} viewBox="0 0 120 120" aria-hidden="true" focusable="false">
      <path d={BIG} fill="var(--gold)" />
      <circle cx="60" cy="60" r="38" fill="none" className={styles.sealRing} strokeWidth="2.5" />
      <path
        d="M42 61l12 12 25-26"
        fill="none"
        className={styles.sealCheck}
        strokeWidth="7"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/**
 * The house illustration (uiux §5.5): three blank index cards fanned out
 * and the gold seal, on the hero ground, drawn from tokens so it follows
 * the theme and palette with no network byte. Used when a campaign has no
 * art, or its art is slow or failed. Never words on the cards.
 */
export function HouseArt({
  width,
  height,
  mirror = false,
  fx = 0.76,
  fy = 0.56,
  fit = 'xMaxYMid slice',
  ground = true,
}: {
  width: number;
  height: number;
  mirror?: boolean;
  fx?: number;
  fy?: number;
  fit?: string;
  /** Paint the hero ground; off where a gradient preset is painted under it. */
  ground?: boolean;
}): React.JSX.Element {
  const x = (v: number): number => (mirror ? width - v : v);
  const scale = Math.min(1, Math.min(width, height) / 800) * 0.92;
  return (
    <svg
      className={styles.house}
      viewBox={`0 0 ${String(width)} ${String(height)}`}
      preserveAspectRatio={fit}
      aria-hidden="true"
      focusable="false"
    >
      {ground && <rect width={width} height={height} fill="var(--hero)" />}
      <circle cx={x(width * 0.78)} cy={height * 0.2} r={height * 0.62} className={styles.glowAccent} />
      <circle cx={x(width * 0.86)} cy={height * 0.92} r={height * 0.38} className={styles.glowGold} />
      <g transform={`translate(${String(x(width * fx))} ${String(height * fy)}) scale(${String(scale)})`}>
        <rect
          x="-210"
          y="-120"
          width="300"
          height="200"
          rx="26"
          transform="rotate(-16)"
          className={styles.cardBack}
          strokeWidth="2"
        />
        <rect
          x="-160"
          y="-150"
          width="300"
          height="200"
          rx="26"
          transform="rotate(-4)"
          className={styles.cardMid}
        />
        <g transform="rotate(9)">
          <rect x="-110" y="-170" width="300" height="200" rx="26" className={styles.cardFront} />
          <rect x="-80" y="-130" width="150" height="18" rx="9" className={styles.lineStrong} />
          <rect x="-80" y="-98" width="210" height="10" rx="5" className={styles.lineSoft} />
          <rect x="-80" y="-78" width="170" height="10" rx="5" className={styles.lineSoft} />
        </g>
        <g transform="translate(150 -150)">
          <path d={sealPath(0, 0, 92, 78, 18)} fill="var(--gold)" className={styles.sealShadow} />
          <circle r="62" fill="none" className={styles.sealRing} strokeWidth="3" />
          <path
            d="M-30 2l20 20 42-44"
            fill="none"
            className={styles.sealCheck}
            strokeWidth="12"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </g>
      </g>
      <g fill="var(--gold)" opacity="0.9" className={styles.sparkles}>
        <path
          transform={`translate(${String(x(width * 0.5))} ${String(height * 0.18)}) scale(2.2)`}
          d={SPARKLE_PATH}
        />
        <path
          transform={`translate(${String(x(width * 0.93))} ${String(height * 0.5)}) scale(1.4)`}
          d={SPARKLE_PATH}
        />
      </g>
    </svg>
  );
}

/** The small square house art (sheet tile, after-milestone card): a card and the seal on gold. */
export function SmallArt(): React.JSX.Element {
  return (
    <svg className={styles.house} viewBox="0 0 112 112" aria-hidden="true" focusable="false">
      <rect width="112" height="112" fill="var(--gold-soft)" />
      <g transform="translate(52 64) rotate(-8)">
        <rect
          x="-34"
          y="-24"
          width="58"
          height="40"
          rx="8"
          fill="var(--surface)"
          className={styles.smallShadow}
        />
        <rect x="-26" y="-14" width="28" height="6" rx="3" fill="var(--accent)" opacity="0.7" />
        <rect x="-26" y="-3" width="38" height="4" rx="2" fill="var(--line2)" />
      </g>
      <g transform="translate(76 38)">
        <path d={sealPath(0, 0, 22, 18.5, 14)} fill="var(--gold)" />
        <path
          d="M-8 1l5 5 11-11"
          fill="none"
          className={styles.sealCheck}
          strokeWidth="3.6"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </g>
    </svg>
  );
}
